CREATE DATABASE IF NOT EXISTS attendance_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE attendance_system;
CREATE TABLE departments (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,code VARCHAR(20) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(60) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('hod','lecturer') NOT NULL,department_id INT NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB;
CREATE TABLE batches (id INT AUTO_INCREMENT PRIMARY KEY,department_id INT NOT NULL,batch_name VARCHAR(120) NOT NULL,batch_code VARCHAR(80) NOT NULL UNIQUE,academic_year VARCHAR(20) NOT NULL,registration_prefix VARCHAR(100) NOT NULL,registration_start INT NOT NULL,registration_end INT NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB;
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY,batch_id INT NOT NULL,registration_number VARCHAR(130) NOT NULL UNIQUE,student_name VARCHAR(120) NULL,email VARCHAR(120) NULL,phone VARCHAR(30) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(batch_id) REFERENCES batches(id)) ENGINE=InnoDB;
CREATE TABLE subjects (id INT AUTO_INCREMENT PRIMARY KEY,department_id INT NOT NULL,semester_id INT NOT NULL,subject_code VARCHAR(30) NOT NULL,subject_name VARCHAR(120) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(department_id,subject_code),FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB;
CREATE TABLE semesters (id INT AUTO_INCREMENT PRIMARY KEY,semester_number TINYINT NOT NULL UNIQUE,semester_name VARCHAR(40) NOT NULL);
INSERT INTO semesters(semester_number,semester_name) VALUES (1,'Semester 1'),(2,'Semester 2'),(3,'Semester 3'),(4,'Semester 4'),(5,'Semester 5'),(6,'Semester 6');
ALTER TABLE subjects ADD CONSTRAINT fk_subject_semester FOREIGN KEY (semester_id) REFERENCES semesters(id);
CREATE TABLE batch_subjects (id INT AUTO_INCREMENT PRIMARY KEY,batch_id INT NOT NULL,semester_id INT NOT NULL,subject_id INT NOT NULL,lecturer_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(batch_id,semester_id,subject_id),FOREIGN KEY(batch_id) REFERENCES batches(id),FOREIGN KEY(semester_id) REFERENCES semesters(id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(lecturer_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE attendance_sessions (id INT AUTO_INCREMENT PRIMARY KEY,batch_subject_id INT NOT NULL,lecture_number TINYINT NOT NULL,session_type ENUM('lecture','practical') NOT NULL,attendance_date DATE NOT NULL,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(batch_subject_id,lecture_number,session_type,attendance_date),FOREIGN KEY(batch_subject_id) REFERENCES batch_subjects(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE attendance_records (id INT AUTO_INCREMENT PRIMARY KEY,attendance_session_id INT NOT NULL,student_id INT NOT NULL,status ENUM('present','absent','medical') NOT NULL,marked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(attendance_session_id,student_id),FOREIGN KEY(attendance_session_id) REFERENCES attendance_sessions(id),FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE medical_adjustments (id INT AUTO_INCREMENT PRIMARY KEY,attendance_record_id INT NOT NULL UNIQUE,previous_status ENUM('present','absent','medical') NOT NULL,action ENUM('converted','reverted') NOT NULL DEFAULT 'converted',note VARCHAR(255) NULL,adjusted_by INT NOT NULL,adjusted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_medical_record (attendance_record_id),FOREIGN KEY(attendance_record_id) REFERENCES attendance_records(id),FOREIGN KEY(adjusted_by) REFERENCES users(id)) ENGINE=InnoDB;
